(x, y, t) => {
  // Normalize coordinates
  let nx = x / 480 - 0.5;
  let ny = y / 240 - 0.5;

  // Domain warping
  let wx = nx + 0.3 * Math.sin(ny * 8 + t * 0.7);
  let wy = ny + 0.3 * Math.cos(nx * 6 + t * 0.5);

  // Second layer of warping
  let wx2 = wx + 0.15 * Math.sin(wy * 12 + t * 1.2);
  let wy2 = wy + 0.15 * Math.cos(wx * 10 - t * 0.9);

  // Create interference patterns
  let d1 = Math.sqrt(wx2 * wx2 + wy2 * wy2);
  let d2 = Math.sqrt((wx2 - 0.3) * (wx2 - 0.3) + (wy2 - 0.2) * (wy2 - 0.2));
  let d3 = Math.sqrt((wx2 + 0.2) * (wx2 + 0.2) + (wy2 + 0.3) * (wy2 + 0.3));

  let v1 = Math.sin(d1 * 30 - t * 2);
  let v2 = Math.sin(d2 * 25 + t * 1.5);
  let v3 = Math.sin(d3 * 20 - t * 1.8);

  let combined = (v1 + v2 + v3) / 3;

  // Add some angular patterns
  let angle = Math.atan2(wy2, wx2);
  let spiral = Math.sin(angle * 5 + d1 * 15 - t * 2.5);

  let final = (combined + spiral) * 0.5;

  // Color mapping using bitwise
  let r = ((Math.sin(final * 3.14 + t) * 127 + 128) | 0) & 255;
  let g = ((Math.sin(final * 3.14 + t + 2.094) * 127 + 128) | 0) & 255;
  let b = ((Math.sin(final * 3.14 + t + 4.188) * 127 + 128) | 0) & 255;

  return [r, g, b];
}

(x, y, t) => {
  // Normalize coordinates
  let nx = x / 480;
  let ny = y / 240;

  // Wave layers - multiple frequencies for complexity
  let w1 = Math.sin(nx * 12 + t * 0.8) * Math.cos(ny * 8 + t * 0.5);
  let w2 = Math.sin(Math.sqrt((nx - 0.5) ** 2 + (ny - 0.5) ** 2) * 20 - t * 1.2);
  let w3 = Math.sin(nx * 6 - ny * 4 + t * 0.6) * 0.5;

  // Combined wave
  let wave = (w1 + w2 * 0.7 + w3) / 2.2;

  // Grid overlay
  let gx = (x % 40 < 2) ? 1 : 0;
  let gy = (y % 30 < 2) ? 1 : 0;
  let grid = Math.max(gx, gy);

  // Color palette - deep ocean theme
  let r = Math.floor((20 + wave * 30 + grid * 60) * (0.8 + w2 * 0.2));
  let g = Math.floor((40 + wave * 60 + grid * 80 + w1 * 20) * (0.8 + w3 * 0.2));
  let b = Math.floor((80 + wave * 80 + grid * 100 + w2 * 30) * (0.9 + w1 * 0.1));

  return [
    Math.max(0, Math.min(255, r)),
    Math.max(0, Math.min(255, g)),
    Math.max(0, Math.min(255, b))
  ];
}

(x, y, t) => {
  // Normalize coordinates
  const nx = x / 480;
  const ny = y / 240;

  // Grid base
  const gx = x % 40;
  const gy = y % 30;
  const gridIntensity = (gx < 1 || gy < 1) ? 40 : 0;

  // Hexagonal grid
  const hx = (x * 0.0866 - y * 0.05);
  const hy = (x * 0.05 + y * 0.0866);
  const hexDist = Math.sqrt(((hx % 1) - 0.5) ** 2 + ((hy % 1) - 0.5) ** 2);
  const hexBorder = hexDist > 0.4 ? 1 : 0;

  // Complex wave patterns
  const wave1 = Math.sin(x * 0.02 + t) * Math.cos(y * 0.03 + t * 0.7);
  const wave2 = Math.sin(Math.sqrt((x - 240) ** 2 + (y - 120) ** 2) * 0.05 - t * 2);

  // Bitwise patterns
  const bit = ((x ^ y) & 31) / 31;

  // Combine
  let r = gridIntensity + hexBorder * 30 + wave1 * 20;
  let g = gridIntensity + hexBorder * 50 + wave2 * 30;
  let b = 40 + hexBorder * 60 + bit * 20;

  return [r, g, b];
}

(x, y, t) => {
  let gx = x % 24, gy = y % 24;
  let grid = ((gx === 0 | gy === 0) ? 1 : 0);
  let dot = (gx === 12 & gy === 12) ? 1 : 0;

  // Multiple layered sine waves
  let v1 = Math.sin(x * 0.02 + t * 1.3) * Math.cos(y * 0.03 - t * 0.7);
  let v2 = Math.sin(Math.sqrt((x-240)**2 + (y-120)**2) * 0.05 - t * 2);
  let v3 = Math.sin((x ^ y) * 0.01 + t);
  let v4 = Math.cos(x * 0.01 * Math.sin(t * 0.5) + y * 0.01 * Math.cos(t * 0.3));

  let plasma = (v1 + v2 + v3 + v4) * 0.25;

  // Panel regions
  let panel = (y < 20) | (y > 220) | (x < 16) | (x > 464);
  let subpanel = (y > 20 & y < 40 & x > 200 & x < 460);

  // Color mapping
  let r = Math.sin(plasma * Math.PI + t) * 127 + 128;
  let g = Math.cos(plasma * Math.PI * 1.3 - t * 0.5) * 127 + 128;
  let b = Math.sin(plasma * Math.PI * 0.7 + t * 0.8) * 80 + 60;

  // Apply grid and dots
  r = r * (1 - grid * 0.7) + grid * 40;
  g = g * (1 - grid * 0.7) + grid * 80;
  b = b * (1 - grid * 0.7) + grid * 120;

  r = r * (1 - dot * 0.5) + dot * 200;
  g = g * (1 - dot * 0.5) + dot * 220;
  b = b * (1 - dot * 0.5) + dot * 255;

  // Apply panel darkening
  r = r * (1 - panel * 0.6) + panel * 15;
  g = g * (1 - panel * 0.6) + panel * 25;
  b = b * (1 - panel * 0.6) + panel * 45;

  // Subpanel highlight
  r = r * (1 - subpanel * 0.3) + subpanel * 100;
  g = g * (1 - subpanel * 0.3) + subpanel * 150;
  b = b * (1 - subpanel * 0.3) + subpanel * 200;

  return [
    r & 255,
    g & 255,
    b & 255
  ];
}
